mapper.select:
/* main.getTeamDocStatusCount : 팀원별 막대 (완성형) */ SELECT U.ORGAID, COALESCE(H.OBJTTX, U.ORGAID) AS TEAM_NAME, U.USER_NAME, U.USER_ID AS DOC_OWNER,
/* ======================= PROD (제품개발) ======================= */ IFNULL(V.PROD_REG_CNT, 0) AS PROD_REG_CNT, IFNULL(V.PROD_APPR_CNT, 0) AS PROD_APPR_CNT, IFNULL(V.PROD_COND_APPR_CNT, 0) AS PROD_COND_APPR_CNT, IFNULL(V.PROD_COMP_CNT, 0) AS PROD_COMP_CNT, IFNULL(V.PROD_TMP_CNT, 0) AS PROD_TMP_CNT, IFNULL(V.PROD_RET_CNT, 0) AS PROD_RET_CNT,
/* ======================= MENU (메뉴개발) ======================= */ IFNULL(V.MENU_REG_CNT, 0) AS MENU_REG_CNT, IFNULL(V.MENU_APPR_CNT, 0) AS MENU_APPR_CNT, IFNULL(V.MENU_COND_APPR_CNT, 0) AS MENU_COND_APPR_CNT, IFNULL(V.MENU_COMP_CNT, 0) AS MENU_COMP_CNT, IFNULL(V.MENU_TMP_CNT, 0) AS MENU_TMP_CNT, IFNULL(V.MENU_RET_CNT, 0) AS MENU_RET_CNT,
/* ======================= DESIGN (상품설계) ======================= */ IFNULL(V.DESIGN_REG_CNT, 0) AS DESIGN_REG_CNT, IFNULL(V.DESIGN_APPR_CNT, 0) AS DESIGN_APPR_CNT, IFNULL(V.DESIGN_COND_APPR_CNT, 0) AS DESIGN_COND_APPR_CNT, IFNULL(V.DESIGN_COMP_CNT, 0) AS DESIGN_COMP_CNT, IFNULL(V.DESIGN_TMP_CNT, 0) AS DESIGN_TMP_CNT, IFNULL(V.DESIGN_RET_CNT, 0) AS DESIGN_RET_CNT,
/* ======================= SENSE_QUALITY (관능품질) ======================= */ IFNULL(V.SENSE_QUALITY_REG_CNT, 0) AS SENSE_QUALITY_REG_CNT, IFNULL(V.SENSE_QUALITY_APPR_CNT, 0) AS SENSE_QUALITY_APPR_CNT, IFNULL(V.SENSE_QUALITY_COND_APPR_CNT, 0) AS SENSE_QUALITY_COND_APPR_CNT, IFNULL(V.SENSE_QUALITY_COMP_CNT, 0) AS SENSE_QUALITY_COMP_CNT, IFNULL(V.SENSE_QUALITY_TMP_CNT, 0) AS SENSE_QUALITY_TMP_CNT, IFNULL(V.SENSE_QUALITY_RET_CNT, 0) AS SENSE_QUALITY_RET_CNT,
/* ======================= PLAN (출장계획) ======================= */ IFNULL(V.PLAN_REG_CNT, 0) AS PLAN_REG_CNT, IFNULL(V.PLAN_APPR_CNT, 0) AS PLAN_APPR_CNT, IFNULL(V.PLAN_COND_APPR_CNT, 0) AS PLAN_COND_APPR_CNT, IFNULL(V.PLAN_COMP_CNT, 0) AS PLAN_COMP_CNT, IFNULL(V.PLAN_TMP_CNT, 0) AS PLAN_TMP_CNT, IFNULL(V.PLAN_RET_CNT, 0) AS PLAN_RET_CNT,
/* ======================= TRIP (출장결과) ======================= */ IFNULL(V.TRIP_REG_CNT, 0) AS TRIP_REG_CNT, IFNULL(V.TRIP_APPR_CNT, 0) AS TRIP_APPR_CNT, IFNULL(V.TRIP_COND_APPR_CNT, 0) AS TRIP_COND_APPR_CNT, IFNULL(V.TRIP_COMP_CNT, 0) AS TRIP_COMP_CNT, IFNULL(V.TRIP_TMP_CNT, 0) AS TRIP_TMP_CNT, IFNULL(V.TRIP_RET_CNT, 0) AS TRIP_RET_CNT,
/* ======================= RESEARCH (시장조사) ======================= */ IFNULL(V.RESEARCH_REG_CNT, 0) AS RESEARCH_REG_CNT, IFNULL(V.RESEARCH_APPR_CNT, 0) AS RESEARCH_APPR_CNT, IFNULL(V.RESEARCH_COND_APPR_CNT, 0) AS RESEARCH_COND_APPR_CNT, IFNULL(V.RESEARCH_COMP_CNT, 0) AS RESEARCH_COMP_CNT, IFNULL(V.RESEARCH_TMP_CNT, 0) AS RESEARCH_TMP_CNT, IFNULL(V.RESEARCH_RET_CNT, 0) AS RESEARCH_RET_CNT,
/* ======================= RESULT (신제품품질) ======================= */ IFNULL(V.RESULT_REG_CNT, 0) AS RESULT_REG_CNT, IFNULL(V.RESULT_APPR_CNT, 0) AS RESULT_APPR_CNT, IFNULL(V.RESULT_COND_APPR_CNT, 0) AS RESULT_COND_APPR_CNT, IFNULL(V.RESULT_COMP_CNT, 0) AS RESULT_COMP_CNT, IFNULL(V.RESULT_TMP_CNT, 0) AS RESULT_TMP_CNT, IFNULL(V.RESULT_RET_CNT, 0) AS RESULT_RET_CNT,
/* ======================= CHEMICAL (이화학검사) ======================= */ IFNULL(V.CHEMICAL_REG_CNT, 0) AS CHEMICAL_REG_CNT, IFNULL(V.CHEMICAL_APPR_CNT, 0) AS CHEMICAL_APPR_CNT, IFNULL(V.CHEMICAL_COND_APPR_CNT, 0) AS CHEMICAL_COND_APPR_CNT, IFNULL(V.CHEMICAL_COMP_CNT, 0) AS CHEMICAL_COMP_CNT, IFNULL(V.CHEMICAL_TMP_CNT, 0) AS CHEMICAL_TMP_CNT, IFNULL(V.CHEMICAL_RET_CNT, 0) AS CHEMICAL_RET_CNT,
/* ======================= PACKAGE (표시사항기재) ======================= */ IFNULL(V.PACKAGE_REG_CNT, 0) AS PACKAGE_REG_CNT, IFNULL(V.PACKAGE_APPR_CNT, 0) AS PACKAGE_APPR_CNT, IFNULL(V.PACKAGE_COND_APPR_CNT, 0) AS PACKAGE_COND_APPR_CNT, IFNULL(V.PACKAGE_COMP_CNT, 0) AS PACKAGE_COMP_CNT, IFNULL(V.PACKAGE_TMP_CNT, 0) AS PACKAGE_TMP_CNT, IFNULL(V.PACKAGE_RET_CNT, 0) AS PACKAGE_RET_CNT
FROM lab_user U LEFT JOIN lab_interface_hr1010 H ON H.OBJTID = U.ORGAID LEFT JOIN lab_doc_status_view V ON U.USER_ID = V.DOC_OWNER WHERE U.ORGAID = #{ORGAID} AND U.EMSTAT = '1' ORDER BY U.USER_NAME
